/**
 * Build the setup-guide's data model from the real catalog — so the human-facing UI
 * generated by `setup:infra:guide` can NEVER drift from `infra.config.ts` + the presets.
 * Pure (no IO), so it is unit-testable.
 */
import { getEnvironmentNames } from '@setup/common/config.js';
import type { SetupConfig } from '@setup/common/types.js';
import { FRONTEND_ENV_KEY_MAPPINGS } from '@setup/envs/frontend-env-keys.js';
import type { Preset } from '@setup/presets/index.js';

/** Where a service's keys go: filled once (account), pasted per env, or generated locally. */
export type GuideGroup = 'account' | 'paste' | 'auto';

/** Live per-environment configuration state (presence only — never a value). */
export type ServiceStatus = 'complete' | 'partial' | 'missing';

export interface GuideService {
  name: string;
  kind: string;
  group: GuideGroup;
  dashboard?: { url: string; label: string };
  /** `.setup/.setup-credentials` vars to fill (account group). */
  credentials: string[];
  /** Env vars this service produces / you paste into `.env.<env>`. */
  outputs: string[];
  /** Mirrored clinozy-fe `VITE_*` keys, if any. */
  feKeys: string[];
  /** Ordered one-by-one walkthrough (from the preset, else derived from the catalog). */
  steps: string[];
  /** Live status per environment (added by {@link withStatus}). */
  status?: Record<string, ServiceStatus>;
}

/** Injectable readers so status can be computed purely (and unit-tested). */
export interface GuideStatusDeps {
  /** Value of `key` in `.env.<env>` (undefined when absent). Never the secret is stored here. */
  readEnvValue(environmentName: string, key: string): string | undefined;
  /** Whether a `.setup/.setup-credentials` var is filled (presence only). */
  hasCredential(name: string): boolean;
}

export interface GuideData {
  project: string;
  credsFile: string;
  environments: string[];
  services: GuideService[];
}

const FE_MAP = new Map<string, string>(FRONTEND_ENV_KEY_MAPPINGS.map((m) => [m.canonical, m.vite]));

function feKeysFor(name: string, outputs: string[]): string[] {
  const out: string[] = [];
  for (const key of outputs) {
    const vite = FE_MAP.get(key);
    if (vite) out.push(vite);
  }
  // Sentry also ships the build-time identifiers into clinozy-fe.
  if (name === 'Sentry') out.push('SENTRY_ORG', 'SENTRY_PROJECT');
  return out;
}

function groupOf(preset: Preset): GuideGroup {
  if (preset.perEnv) return 'paste';
  if (preset.credentials && preset.credentials.length > 0) return 'account';
  return 'auto';
}

/** Steps from the preset, else derived from its group/credentials/outputs. Keeps the guide in sync. */
function stepsFor(
  service: Pick<GuideService, 'group' | 'dashboard' | 'credentials' | 'outputs'>,
  credsFile: string,
  explicit: string[] | undefined,
): string[] {
  if (explicit && explicit.length > 0) return explicit;
  const open = service.dashboard
    ? `Open ${service.dashboard.label}.`
    : 'Open the provider dashboard.';
  if (service.group === 'account') {
    return [
      open,
      'Create the key and copy it.',
      `Paste ${service.credentials.join(' / ')} into ${credsFile}.`,
      service.outputs.length > 0
        ? `Run pnpm setup:infra — it provisions the resource and writes ${service.outputs.join(', ')}.`
        : 'Run pnpm setup:infra to apply.',
    ];
  }
  if (service.group === 'paste') {
    return [
      open,
      'Create the resource — one per environment.',
      `Copy the values and paste ${service.outputs.join(' / ')} into .env.<env>.`,
    ];
  }
  return [
    `Nothing to fetch — run pnpm setup:infra and ${
      service.outputs.join(', ') || 'the values'
    } are generated locally.`,
  ];
}

/** Derive the guide model from config + the preset catalog. `environments` scopes to a subset (-e). */
export function buildGuideData(
  config: SetupConfig,
  presets: readonly Preset[],
  options: { environments?: string[] } = {},
): GuideData {
  const allEnvironments = getEnvironmentNames(config);
  const scoped = options.environments?.length
    ? allEnvironments.filter((e) => options.environments?.includes(e))
    : allEnvironments;
  const environments = scoped.length > 0 ? scoped : allEnvironments;

  const credsFile = '.setup/.setup-credentials';
  const services: GuideService[] = presets.map((preset) => {
    const outputs = (preset.outputs ?? []).map((o) => o.key);
    const base = {
      name: preset.name,
      kind: preset.kind,
      group: groupOf(preset),
      ...(preset.dashboard ? { dashboard: preset.dashboard } : {}),
      credentials: preset.credentials ?? [],
      outputs,
      feKeys: feKeysFor(preset.name, outputs),
    };
    return { ...base, steps: stepsFor(base, credsFile, preset.steps) };
  });

  return {
    project: config.project.name,
    credsFile,
    environments,
    services,
  };
}

function nonEmpty(value: string | undefined): boolean {
  return typeof value === 'string' && value.trim().length > 0;
}

/** Live status of one service for one environment (presence of its keys, never values). */
export function serviceStatusFor(
  service: GuideService,
  environmentName: string,
  deps: GuideStatusDeps,
): ServiceStatus {
  if (service.outputs.length > 0) {
    const present = service.outputs.filter((key) =>
      nonEmpty(deps.readEnvValue(environmentName, key)),
    ).length;
    if (present === service.outputs.length) return 'complete';
    return present > 0 ? 'partial' : 'missing';
  }
  // Services that write no .env keys (GitHub/Scalar) are "set" once their credential is filled.
  if (service.credentials.length > 0) {
    return service.credentials.every((name) => deps.hasCredential(name)) ? 'complete' : 'missing';
  }
  return 'missing';
}

/** Attach live per-environment status to every service. Pure given `deps`. */
export function withStatus(data: GuideData, deps: GuideStatusDeps): GuideData {
  const services = data.services.map((service) => ({
    ...service,
    status: Object.fromEntries(
      data.environments.map((env) => [env, serviceStatusFor(service, env, deps)]),
    ),
  }));
  return { ...data, services };
}
